mapper.select:
SELECT area_id,
alarm_suppress_id,
device_code,
dev_name,
channel_code,
area_name,
overlap_rate,
area_type,
points,
points_pt,
points_p,
points_t,
p_min,
p_max,
t_min,
t_max,
screenshot,
tenant_id,
creater_by,
create_time,
update_by,
update_time,
delete_flag
FROM vm_alarm_area_suppress
WHERE delete_flag = 0
 and vm_alarm_area_suppress.area_id = #{areaId,jdbcType=INTEGER}
 and vm_alarm_area_suppress.alarm_suppress_id = #{alarmSuppressId,jdbcType=INTEGER}
 and vm_alarm_area_suppress.device_code = #{deviceCode,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.channel_code = #{channelCode,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.area_name = #{areaName,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.overlap_rate = #{overlapRate,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.area_type = #{areaType,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.points = #{points,jdbcType=LONGVARCHAR}
 and vm_alarm_area_suppress.points_p = #{pointsP,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.points_t = #{pointsT,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.p_min = #{pMin,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.p_max = #{pMax,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.t_min = #{tMin,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.t_max = #{tMax,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.tenant_id = #{tenantId,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.creater_by = #{createrBy,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.create_time = #{createTime,jdbcType=TIMESTAMP}
 and vm_alarm_area_suppress.create_time BETWEEN #{startDate} and #{endDate}
 and vm_alarm_area_suppress.update_by = #{updateBy,jdbcType=VARCHAR}
 and vm_alarm_area_suppress.update_time = #{updateTime,jdbcType=TIMESTAMP}
 and vm_alarm_area_suppress.delete_flag = #{deleteFlag,jdbcType=VARCHAR}
 and alarm_suppress_id in

		#{strategyId}




		order by create_time asc


		order by create_time desc


		order by update_time asc


		order by update_time desc


		order by area_id desc

SELECT `uav_area_id`, `alarm_suppress_id`, `uav_device_code`, `uav_device_name`, `flight_route_id`, `area_name`, `layer_id`, `point`, `point_json`, `flight_route_name`, `tenant_id`, `industry_code`, `delete_flag`, `create_time`, `update_time`, `create_user`, `update_user` FROM vm_alarm_uav_area_suppress where delete_flag= '0' and uav_device_code = #{deviceCode} and flight_route_id = #{flightRouteId} and alarm_suppress_id in
#{strategyId}
order by uav_area_id desc
